using System.Text.Json.Serialization;
using Hexalith.Agents.Contracts.AgentInteraction;
namespace Hexalith.Agents.Server.Application.Workflows;

/// <summary>AD-27 workflow input, activity input/output and custom status; never raw request or generated bytes.</summary>
/// <param name="TenantId">The TenantId binding.</param>
/// <param name="ConversationId">The ConversationId binding.</param>
/// <param name="AgentInteractionId">The AgentInteractionId binding.</param>
/// <param name="RequestReference">The RequestReference binding.</param>
/// <param name="EventRevision">The EventRevision binding.</param>
/// <param name="Status">The Status binding.</param>
/// <param name="Outcome">The exact last recorded phase outcome from the shared twin policy.</param>
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)]
public sealed record WorkflowExecutionState(string TenantId, string ConversationId, string AgentInteractionId, ProtectedContentReference RequestReference, long EventRevision, WorkflowExecutionStatus Status, AutomaticInteractionOutcome Outcome = AutomaticInteractionOutcome.Unknown);
